function autoChoice(choices){let best=0,score=-1e9;choices.forEach((c,i)=>{let s=Math.random();if(/ปลอดภัย|ถอนตัว|ปฏิเสธ|พักผ่อน/.test(c)&&g.health<45)s+=8;if(/เรียน|ศึกษา|ฝึก/.test(c)&&g.age<23)s+=4;if(/งาน|ธุรกิจ|อาชีพ|เงิน/.test(c)&&g.money<15)s+=5;if(/เพื่อน|ครอบครัว|สังคม/.test(c)&&g.social<45)s+=4;if(/สำรวจ|ภารกิจ|ฮันเตอร์/.test(c)&&g.awakened&&g.health>65)s+=3;if(/ค้นหา|ความจริง/.test(c)&&g.personality==='ใฝ่รู้')s+=5;if(/กล้า|ต่อสู้|สำรวจ/.test(c)&&g.personality==='กล้าหาญ')s+=3;if(/ปลอดภัย|ระมัดระวัง/.test(c)&&g.personality==='ระมัดระวัง')s+=5;if(/ครอบครัว/.test(c)&&g.goal==='ช่วยเหลือครอบครัว')s+=6;if(/งาน|อาชีพ|เงิน/.test(c)&&g.goal==='มีอิสรภาพทางการเงิน')s+=5;if(/ความจริง|Gate|เกต/.test(c)&&g.goal==='ค้นหาความจริงของ Gate')s+=6;if(s>score){score=s;best=i}});return best}
